def page_after(ids, after, limit):
    """Return a page of numeric-string ids in project cursor order.

    Ids are ordered by numeric value; ties between distinct strings with the
    same numeric value keep their first-seen input order (stable sort).
    Exact duplicate ids are kept only at their first occurrence. ``after`` is
    an original id string; the page starts after that id's position. A None
    ``after`` starts from the beginning. ``limit`` must be a non-negative int
    (bool is rejected). The input sequence is never modified.
    """
    if isinstance(limit, bool) or not isinstance(limit, int) or limit < 0:
        raise ValueError("limit must be a non-negative integer")

    seen = set()
    unique = []
    for value in ids:
        _parse_id(value)
        if value in seen:
            continue
        seen.add(value)
        unique.append(value)

    if after is not None:
        _parse_id(after)
        if after not in seen:
            raise ValueError("unknown after id")

    ordered = sorted(unique, key=_parse_id)

    if after is None:
        start = 0
    else:
        start = ordered.index(after) + 1

    return ordered[start:start + limit]

